def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.159.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.158.0"' not in init:
        sys.exit("ABORT: not at v3.158.0.")
    for k in ("banking", "ar_ap_chair"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("ACC3", LESSONS_A3, QUESTIONS_A3, 9) + _validate("ACC4", LESSONS_A4, QUESTIONS_A4, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("ACC 3", LESSONS_A3, QUESTIONS_A3, "banking",
         "Banking and reconciliation: the bank statement as the record the business does not write, the account and payment-mode wiring, the monthly matching routine with the reconciliation equation, the three remainder categories with written age limits, the imprest float and its invariant, the four-link retail cash-up chain, and bank governance — prepare/release separation, masters-not-messages, and the mandate review."),
        ("ACC 4", LESSONS_A4, QUESTIONS_A4, "ar_ap_chair",
         "Receivables and payables from the accounts chair: the record kept real, collectable, current and complete — the monthly tie check, the unallocated read worked to near-zero, advances in both directions under the never-net rule, provisioning by aging matrix with governed write-offs and recoveries, statements and confirmations with the supplier-statement mirror, detail-never-blobs migration, and the ninety-minute month-end ritual."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v2: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.158.0"', '"3.159.0"'))
    print("  data: ACCOUNTS 3 + 4 lessons + banks REPLACED (style v2.1)")
    print("wrote __version__ -> 3.159.0")


if __name__ == "__main__":
    main()
